/* ---------------- cards ---------------- */
let uid=0;
function mk(rank,suit,color){const c={id:++uid,rank,suit,color:color||(suit==="H"||suit==="D"?"red":"black"),owner:null};if(rank==="A"){c.hp=2;c.maxHp=2}return c}   // every Ace is a base with two hearts
