  const fixed={offensive:FA_OFF,defensive:AI.W.DEF,center:FA_CENTER,skirmish:FA_SKIRM}[c.stance];if(fixed)W=faMix(W,fixed,sc.stance);
  if(faRushing(pl))W=faMix(W,AI.W.PUSH,sc.rush);
