{const _cr=cycleRound;cycleRound=function(){try{if(G&&typeof payDay==="function"&&payDay()){const a=G.payHist=G.payHist||[];if(a[a.length-1]!==G.moon.round)a.push(G.moon.round)}}catch(e){}return _cr.apply(this,arguments)}}
