    const keep={n:P.sunNext,f:P.sunFrom};P.sunNext=tnOf(pl);G.skyGlow=true;render();
    try{await skyAsync(pl)}finally{P.sunNext=keep.n;P.sunFrom=keep.f;G.skyGlow=false}
