  m.hidden=false;const w=m.offsetWidth||180,h=m.offsetHeight||200;m.style.left=Math.max(6,Math.min(innerWidth-w-6,x))+scrollX+"px";m.style.top=Math.max(6,Math.min(innerHeight-h-6,y))+scrollY+"px";
